import{_ as t,o as i,c as n,a4 as s}from"./chunks/framework.BE47AOxC.js";const p=JSON.parse('{"title":"ADR-0062 — Signature des images par cosign v3","description":"Extrait de docs/adr/0062-signature-par-cosign-v3.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0062 — Signature des images par cosign v3","description":"Extrait de docs/adr/0062-signature-par-cosign-v3.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0062-signature-par-cosign-v3.md","filePath":"developpeurs/adr/0062-signature-par-cosign-v3.md"}'),a={name:"developpeurs/adr/0062-signature-par-cosign-v3.md"};function r(o,e,c,l,u,d){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0062--signature-des-images-par-cosign-v3" tabindex="-1">ADR-0062 — Signature des images par cosign v3 <a class="header-anchor" href="#adr-0062--signature-des-images-par-cosign-v3" aria-label="Permalink to &quot;ADR-0062 — Signature des images par cosign v3 {#adr-0062--signature-des-images-par-cosign-v3}&quot;">​</a></h1><p><strong>Date :</strong> 29 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> passage des actions GitHub sous Node 24 (lot 6 de l&#39;audit du 26 septembre 2026) : <code>sigstore/cosign-installer</code> v4 installe cosign v3 par défaut <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0057-authenticite-des-images-a-l-installation">ADR-0057</a>, décisions n°3 et n°4 (vérification par cosign à l&#39;installation)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le lot 6 a fait passer <code>sigstore/cosign-installer</code> à la v4. Par défaut, cette version installe cosign v3. Le workflow restait épinglé sur cosign v2.6.5, faute de décision.</p><p>cosign v3 active par défaut ce qui était optionnel en v2.6 :</p><ul><li>le format de bundle Sigstore normalisé ;</li><li>la racine de confiance et la configuration de signature tirées par TUF ;</li><li>surtout, <strong>la signature d&#39;une image rangée en artefact OCI 1.1 référent</strong>, au lieu de l&#39;étiquette <code>sha256-….sig</code>.</li></ul><p>Un cosign v2 ne cherche pas ce référent. Il ne trouve donc aucune signature sur une image signée en v3, même authentique.</p><p>Sigstore annonce que la v3 aura peu de versions et que la v4 retirera l&#39;ancien fonctionnement. Rester en v2 reporterait le changement en le rendant plus brutal. Aucune release n&#39;a encore été publiée avec <code>images-publiees.txt</code> (ADR-0057, action ouverte) : aucun serveur ne vérifie déjà une signature v2.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Le workflow signe avec cosign v3</strong>, en version épinglée : <code>cosign-release: v3.1.3</code> dans <code>publication-images.yml</code>, et non le défaut de l&#39;action. La v3.1.3 corrige GHSA-fx35-mq7g-6g98, un contournement de vérification par une clé publique glissée dans un bundle ancien. <code>cosign sign --yes</code> par empreinte reste inchangé.</li><li><strong>L&#39;installateur exige cosign v3 ou plus récent pour vérifier.</strong> Il lit la version majeure par <code>cosign version</code> (constante <code>COSIGN_MAJEURE_MIN=3</code> dans <code>deploy/installer.sh</code>). Un cosign plus ancien, ou dont la version est illisible, est traité <strong>comme un cosign absent</strong> : un avertissement dit que la signature n&#39;est pas vérifiée et pourquoi, et comment installer une version récente, puis l&#39;installation continue. L&#39;empreinte reste vérifiée dans tous les cas (ADR-0057, décision n°2).</li><li>L&#39;identité attendue (workflow, étiquette de version) et l&#39;émetteur OIDC ne changent pas. Un cosign v3 qui refuse la signature arrête toujours l&#39;installation.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Rester en cosign v2.6.5</strong></td><td>La branche v2 ne reçoit plus que des correctifs, et la v4 supprimera l&#39;ancien format : le passage serait seulement reporté.</td></tr><tr><td><strong>Signer aux deux formats</strong> (v3, puis <code>--new-bundle-format=false</code>)</td><td>Deux signatures à maintenir pour des serveurs qui n&#39;existent pas encore : aucune release n&#39;a été vérifiée en v2.</td></tr><tr><td><strong>Laisser un cosign v2 échouer</strong></td><td>Il échouerait sur une image authentique, et le message dirait « signature non vérifiée » : l&#39;exploitant croirait à une attaque.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Signature au format actuel de Sigstore, et version de cosign corrigée de GHSA-fx35-mq7g-6g98.</li><li>Un serveur équipé d&#39;un cosign trop ancien reçoit un message juste, et non une fausse alerte.</li></ul><p><strong>Négatives</strong></p><ul><li>Un serveur qui a cosign v2 ne vérifie pas la signature tant qu&#39;il n&#39;est pas mis à jour ; l&#39;avertissement le dit.</li><li>La commande <code>cosign verify</code> des notes de version suppose cosign v3 ; les notes le précisent.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Workflow en cosign v3.1.3, installateur qui exige la v3 pour vérifier, tests — <code>.github/workflows/publication-images.yml</code> (<code>cosign-release: v3.1.3</code>), <code>deploy/installer.sh</code> (<code>COSIGN_MAJEURE_MIN</code>, <code>verifier_authenticite_images</code>), <code>deploy/tests/installer.bats</code> (cosign v2 et version illisible), <code>deploy/LISEZMOI.md</code>.</li><li>[x] Première release signée en v3 et vérifiée par une installation réelle avec cosign v3 : elle rejoint l&#39;action ouverte de l&#39;ADR-0057. <strong>Fait le 30/09/2026</strong> — release v0.2.1 (<code>calamars</code> et <code>teuthis-cms-distribution</code>), images <code>teuthis-api@sha256:78ce6fcb…</code> et <code>teuthis-admin@sha256:fdbccfe2…</code> publiques ; installation réelle sur un Ubuntu 24.04 jetable, sans compte GitHub, avec cosign v3.1.3 : installateur et archive vérifiés par leur somme, « Signature vérifiée » et « Empreinte conforme » pour les deux images, six services sains, <code>/api/sante</code> en HTTPS (200). <code>cosign verify</code> refuse la même image contre l&#39;étiquette <code>v9.9.9</code> (contre-épreuve).</li></ul>',19)])])}const v=t(a,[["render",r]]);export{p as __pageData,v as default};
